// Tests for RecipeWizard — the recipe-create step machine (2b-T5).
//
// Scope (this task): Trigger step + Action step + the 4-pill step indicator.
// Constraints + Review steps are minimal placeholders (Task 6 fills them in).
//
// The api module is mocked so the wizard's on-mount loads resolve
// synchronously to fixed shapes:
//   - listTriggerTypes → 4 triggers (incl. keyword_detected w/ keywords + match)
//   - listActionTypes  → 11 actions (4 supported + 7 unsupported)
//   - listContactGroups / listChannels → one option each
//
// Queries by role/text/label — never getByTestId.

import { render, screen, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, it, expect, vi, beforeEach } from "vitest";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { RecipeWizard } from "../../../src/components/recipes/RecipeWizard";
import {
  createRecipe,
  updateRecipe,
  testRecipeDraft,
  type Recipe,
  type TriggerTypeInfo,
  type ActionTypeInfo,
} from "../../../src/api/recipes";

// ─── Fixtures ─────────────────────────────────────────────────────────────────

const TRIGGERS: TriggerTypeInfo[] = [
  {
    key: "message_received",
    label: "Message received",
    description: "Fires when any inbound message arrives.",
    config_schema: { fields: [] },
  },
  {
    key: "keyword_detected",
    label: "Keyword detected",
    description: "Fires when an inbound message matches keywords.",
    config_schema: {
      fields: [
        { name: "keywords", type: "string_list", required: true, label: "Keywords" },
        { name: "match", type: "enum:any|all", required: false, label: "Match" },
      ],
    },
  },
  {
    key: "contact_created",
    label: "Contact created",
    description: "Fires when a new contact is created.",
    config_schema: { fields: [] },
  },
  {
    key: "conversation_opened",
    label: "Conversation opened",
    description: "Fires when a conversation is opened.",
    config_schema: { fields: [] },
  },
];

function action(
  key: string,
  label: string,
  supported: boolean,
  fields: ActionTypeInfo["config_schema"]["fields"] = [],
): ActionTypeInfo {
  return {
    key,
    label,
    description: `${label} action`,
    supported,
    config_schema: { fields },
  };
}

const ACTIONS: ActionTypeInfo[] = [
  action("send_message", "Send a message", true),
  action("auto_tag", "Auto-tag", true),
  action("add_to_group", "Add to group", true),
  action("set_priority", "Set priority", true),
  action("add_note", "Add a note", true, [
    { name: "template", type: "text", required: true, label: "Note template" },
  ]),
  action("assign_agent", "Assign agent", false),
  action("create_task", "Create task", false),
  action("notify_slack", "Notify Slack", false),
  action("webhook", "Call webhook", false),
  action("escalate", "Escalate", false),
  action("close_conversation", "Close conversation", false),
  action("snooze", "Snooze", false),
];

const SUPPORTED_ACTIONS = ACTIONS.filter((a) => a.supported);
const UNSUPPORTED_ACTIONS = ACTIONS.filter((a) => !a.supported);

vi.mock("../../../src/api/recipes", () => ({
  listTriggerTypes: vi.fn(async () => TRIGGERS),
  listActionTypes: vi.fn(async () => ACTIONS),
  createRecipe: vi.fn(),
  updateRecipe: vi.fn(),
  testRecipeDraft: vi.fn(),
}));

vi.mock("../../../src/api/contactGroups", () => ({
  listContactGroups: vi.fn(async () => ({
    groups: [{ id: "g1", name: "VIP" }],
    next_page_token: "",
  })),
}));

vi.mock("../../../src/api/channels", () => ({
  listChannels: vi.fn(async () => ({
    channels: [{ id: "c1", name: "Support inbox", type: "EMAIL" }],
    next_page_token: "",
  })),
}));

function renderWizard(onDone = vi.fn()) {
  render(<RecipeWizard mode="create" onDone={onDone} onCancel={vi.fn()} />);
  return { onDone };
}

// Drives the wizard from the freshly-loaded Trigger step all the way to the
// Constraints step using the keyword trigger + the add_note action, leaving
// the name field empty. Returns the userEvent instance for the caller.
async function driveToConstraints(user: ReturnType<typeof userEvent.setup>) {
  await screen.findByRole("heading", { name: m.recipes_when_prompt() });
  // Trigger: keyword_detected + one keyword.
  await user.click(screen.getByText("Keyword detected"));
  await user.type(screen.getByLabelText("Keywords"), "invoice{Enter}");
  await user.click(screen.getByRole("button", { name: m.recipes_continue() }));
  // Action: add_note + a template body.
  await screen.findByRole("heading", { name: m.recipes_then_prompt() });
  await user.click(screen.getByText("Add a note"));
  await user.type(screen.getByLabelText(/Note template/), "Flagged");
  await user.click(screen.getByRole("button", { name: m.recipes_continue() }));
  // Now on the Constraints step.
  await screen.findByRole("heading", { name: m.recipes_step_constraints() });
}

describe("RecipeWizard", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("renders a loading state then the Trigger step heading", async () => {
    renderWizard();
    expect(
      await screen.findByRole("heading", { name: m.recipes_when_prompt() }),
    ).toBeInTheDocument();
  });

  it("blocks Continue until a keyword is added, then advances to the Action step", async () => {
    const user = userEvent.setup();
    renderWizard();
    await screen.findByRole("heading", { name: m.recipes_when_prompt() });

    // Select the "Keyword detected" trigger card.
    await user.click(screen.getByText("Keyword detected"));

    // The keyword chip input appears.
    const chipInput = screen.getByLabelText("Keywords");
    expect(chipInput).toBeInTheDocument();

    // Continue is blocked while the required keyword list is empty.
    const continueBtn = screen.getByRole("button", { name: m.recipes_continue() });
    expect(continueBtn).toBeDisabled();

    // Add a keyword.
    await user.type(chipInput, "invoice{Enter}");

    // Now Continue is enabled; clicking it advances to the Action step.
    expect(continueBtn).toBeEnabled();
    await user.click(continueBtn);

    expect(
      await screen.findByRole("heading", { name: m.recipes_then_prompt() }),
    ).toBeInTheDocument();
  });

  it("shows supported action cards enabled and unsupported ones aria-disabled", async () => {
    const user = userEvent.setup();
    renderWizard();
    await screen.findByRole("heading", { name: m.recipes_when_prompt() });

    // Advance to the Action step via the keyword trigger.
    await user.click(screen.getByText("Keyword detected"));
    await user.type(screen.getByLabelText("Keywords"), "invoice{Enter}");
    await user.click(screen.getByRole("button", { name: m.recipes_continue() }));
    await screen.findByRole("heading", { name: m.recipes_then_prompt() });

    // Supported action card present.
    expect(screen.getByText(SUPPORTED_ACTIONS[0].label)).toBeInTheDocument();

    // Coming-soon subsection present.
    expect(screen.getByText(m.recipes_coming_soon())).toBeInTheDocument();

    // At least one unsupported action card is aria-disabled.
    const unsupportedLabel = screen.getByText(UNSUPPORTED_ACTIONS[0].label);
    const card = unsupportedLabel.closest("[aria-disabled]");
    expect(card).not.toBeNull();
    expect(card).toHaveAttribute("aria-disabled", "true");
  });

  it("preserves the keyword when navigating Back from Action to Trigger", async () => {
    const user = userEvent.setup();
    renderWizard();
    await screen.findByRole("heading", { name: m.recipes_when_prompt() });

    await user.click(screen.getByText("Keyword detected"));
    await user.type(screen.getByLabelText("Keywords"), "invoice{Enter}");
    await user.click(screen.getByRole("button", { name: m.recipes_continue() }));
    await screen.findByRole("heading", { name: m.recipes_then_prompt() });

    // Go Back to the Trigger step.
    await user.click(screen.getByRole("button", { name: m.recipes_back() }));
    await screen.findByRole("heading", { name: m.recipes_when_prompt() });

    // The keyword chip is still present (state preserved).
    const chip = within(screen.getByLabelText("Keywords").closest("div")!);
    expect(chip).toBeTruthy();
    expect(screen.getByText("invoice")).toBeInTheDocument();
  });

  // ─── Task 6: Constraints + Review/Test + Submit ───────────────────────────

  it("drives through to the Review step and reads back the name + trigger/action labels", async () => {
    const user = userEvent.setup();
    renderWizard();
    await driveToConstraints(user);

    // Constraints: fill the required name, then Continue.
    await user.type(screen.getByLabelText(m.recipes_name_label()), "Flag invoices");
    await user.click(screen.getByRole("button", { name: m.recipes_continue() }));

    // Review step heading + summary read-back.
    await screen.findByRole("heading", { name: m.recipes_review_heading() });
    expect(screen.getByText("Flag invoices")).toBeInTheDocument();
    expect(screen.getByText("Keyword detected")).toBeInTheDocument();
    expect(screen.getByText("Add a note")).toBeInTheDocument();
  });

  it("runs the test panel against the assembled draft and shows the match + rendered body", async () => {
    vi.mocked(testRecipeDraft).mockResolvedValue({
      trigger_matched: true,
      match_detail: "matched on 'invoice'",
      action_supported: true,
      would_be_action: { rendered_body: "Hi" },
    });
    const user = userEvent.setup();
    renderWizard();
    await driveToConstraints(user);
    await user.type(screen.getByLabelText(m.recipes_name_label()), "Flag invoices");
    await user.click(screen.getByRole("button", { name: m.recipes_continue() }));
    await screen.findByRole("heading", { name: m.recipes_review_heading() });

    await user.click(screen.getByRole("button", { name: m.recipes_test_cta() }));

    const status = await screen.findByRole("status");
    expect(within(status).getByText(m.recipes_test_matched())).toBeInTheDocument();
    expect(within(status).getByText("Hi")).toBeInTheDocument();

    expect(testRecipeDraft).toHaveBeenCalledTimes(1);
    const arg = vi.mocked(testRecipeDraft).mock.calls[0][0];
    expect(arg.trigger_type).toBe("keyword_detected");
    expect(arg.action_type).toBe("add_note");
    expect(arg.sample_trigger_data).toBeDefined();
  });

  it("saves a new recipe via createRecipe and fires onDone with the new id", async () => {
    vi.mocked(createRecipe).mockResolvedValue({
      id: "r1",
      name: "Flag invoices",
      description: "",
      is_active: false,
      trigger_type: "keyword_detected",
      action_type: "add_note",
      channel_id: "",
      channel_type: "",
      cooldown_minutes: 0,
    } as Recipe);
    const user = userEvent.setup();
    const { onDone } = renderWizard();
    await driveToConstraints(user);
    await user.type(screen.getByLabelText(m.recipes_name_label()), "Flag invoices");
    await user.click(screen.getByRole("button", { name: m.recipes_continue() }));
    await screen.findByRole("heading", { name: m.recipes_review_heading() });

    await user.click(screen.getByRole("button", { name: m.recipes_save() }));

    expect(createRecipe).toHaveBeenCalledTimes(1);
    const req = vi.mocked(createRecipe).mock.calls[0][0];
    expect(req.name).toBe("Flag invoices");
    expect(req.trigger_type).toBe("keyword_detected");
    expect(req.action_type).toBe("add_note");
    expect(req.action_config).toMatchObject({ template: "Flagged" });
    expect(onDone).toHaveBeenCalledWith("r1");
  });

  it("blocks Continue on the Constraints step when the name is empty", async () => {
    const user = userEvent.setup();
    renderWizard();
    await driveToConstraints(user);

    // Name is empty — Continue surfaces an inline alert and does not advance.
    await user.click(screen.getByRole("button", { name: m.recipes_continue() }));

    expect(screen.getByRole("alert")).toHaveTextContent(m.recipes_name_required());
    expect(
      screen.queryByRole("heading", { name: m.recipes_review_heading() }),
    ).not.toBeInTheDocument();
    expect(createRecipe).not.toHaveBeenCalled();
  });

  it("shows the load error state when listTriggerTypes rejects", async () => {
    const { listTriggerTypes } = await import("../../../src/api/recipes");
    vi.mocked(listTriggerTypes).mockRejectedValueOnce(new Error("API down"));
    render(<RecipeWizard mode="create" onDone={vi.fn()} onCancel={vi.fn()} />);
    expect(await screen.findByRole("alert")).toBeInTheDocument();
  });

  it("cancel button calls onCancel from the Trigger step", async () => {
    const onCancel = vi.fn();
    const user = userEvent.setup();
    render(<RecipeWizard mode="create" onDone={onCancel} onCancel={onCancel} />);
    await screen.findByRole("heading", { name: m.recipes_when_prompt() });
    // The Cancel button is always visible — it's outside the step content.
    const cancelBtn = screen.getByRole("button", { name: m.recipes_cancel() });
    await user.click(cancelBtn);
    expect(onCancel).toHaveBeenCalledOnce();
  });

  it("shows the save error banner when createRecipe rejects", async () => {
    vi.mocked(createRecipe).mockRejectedValueOnce(new Error("save failed"));
    const user = userEvent.setup();
    renderWizard();
    await driveToConstraints(user);
    await user.type(screen.getByLabelText(m.recipes_name_label()), "Flag invoices");
    await user.click(screen.getByRole("button", { name: m.recipes_continue() }));
    await screen.findByRole("heading", { name: m.recipes_review_heading() });
    await user.click(screen.getByRole("button", { name: m.recipes_save() }));
    expect(await screen.findByRole("alert")).toBeInTheDocument();
  });

  it("shows the test error banner when testRecipeDraft rejects", async () => {
    vi.mocked(testRecipeDraft).mockRejectedValueOnce(new Error("test failed"));
    const user = userEvent.setup();
    renderWizard();
