// Tests for KeywordChipsInput — a chip/pill text input for keyword lists.
//
// Verifies:
//   - typing + Enter commits a chip with a "Remove <kw>" button.
//   - clicking remove fires onChange with the keyword removed.
//   - comma also commits a chip.
//   - duplicate keywords are ignored.
//   - backspace on an empty input removes the last chip.
//
// Queries by role/text — never getByTestId.

import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, it, expect, vi } from "vitest";
import { KeywordChipsInput } from "../../../src/components/recipes/KeywordChipsInput";

function setup(value: string[]) {
  const onChange = vi.fn();
  render(
    <KeywordChipsInput value={value} onChange={onChange} label="Keywords" />,
  );
  return { onChange };
}

describe("KeywordChipsInput", () => {
  it("commits a chip on Enter and shows a Remove button", async () => {
    const user = userEvent.setup();
    const { onChange } = setup([]);
    const input = screen.getByLabelText("Keywords");
    await user.type(input, "refund{Enter}");
    expect(onChange).toHaveBeenCalledWith(["refund"]);
  });

  it("renders an existing chip with a Remove button and removes it on click", async () => {
    const user = userEvent.setup();
    const onChange = vi.fn();
    render(
      <KeywordChipsInput value={["refund"]} onChange={onChange} label="Keywords" />,
    );
    expect(screen.getByText("refund")).toBeInTheDocument();
    const removeBtn = screen.getByRole("button", { name: "Remove refund" });
    await user.click(removeBtn);
    expect(onChange).toHaveBeenCalledWith([]);
  });

  it("commits a chip on comma", async () => {
    const user = userEvent.setup();
    const { onChange } = setup([]);
    const input = screen.getByLabelText("Keywords");
    await user.type(input, "urgent,");
    expect(onChange).toHaveBeenCalledWith(["urgent"]);
  });

  it("ignores a duplicate keyword", async () => {
    const user = userEvent.setup();
    const onChange = vi.fn();
    render(
      <KeywordChipsInput value={["refund"]} onChange={onChange} label="Keywords" />,
    );
    const input = screen.getByLabelText("Keywords");
    await user.type(input, "refund{Enter}");
    expect(onChange).not.toHaveBeenCalled();
  });

  it("trims whitespace before committing", async () => {
    const user = userEvent.setup();
    const { onChange } = setup([]);
    const input = screen.getByLabelText("Keywords");
    await user.type(input, "  spaced  {Enter}");
    expect(onChange).toHaveBeenCalledWith(["spaced"]);
  });

  it("removes the last chip on backspace when the input is empty", async () => {
    const user = userEvent.setup();
    const onChange = vi.fn();
    render(
      <KeywordChipsInput
        value={["a", "b"]}
        onChange={onChange}
        label="Keywords"
      />,
    );
    const input = screen.getByLabelText("Keywords");
    input.focus();
    await user.keyboard("{Backspace}");
    expect(onChange).toHaveBeenCalledWith(["a"]);
  });

  it("does not commit an empty/whitespace-only keyword", async () => {
    const user = userEvent.setup();
    const { onChange } = setup([]);
    const input = screen.getByLabelText("Keywords");
    await user.type(input, "   {Enter}");
    expect(onChange).not.toHaveBeenCalled();
  });
});


