// Tests for RecipeRowActions — per-row activate/deactivate toggle, edit link,
// and delete (with confirm dialog) controls on the recipes list.
//
// Behaviors:
//   - toggle an inactive recipe → activateRecipe called, aria-checked flips to
//     true optimistically; onChanged invoked with the updated recipe.
//   - toggle failure → rolls back to unchecked + an inline error appears.
//   - Edit link points at /dialogue/recipes/{id}/edit.
//   - Delete opens a confirm dialog; confirming calls deleteRecipe(id) then
//     onChanged(null); cancel closes the dialog and keeps the row.
//
// Queries by role/name/text — never getByTestId.

import { render, screen, waitFor, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { MemoryRouter } from "react-router-dom";
import { describe, it, expect, vi, beforeEach } from "vitest";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { RecipeRowActions } from "../../../src/components/recipes/RecipeRowActions";
import type { Recipe } from "../../../src/api/recipes";

vi.mock("../../../src/api/recipes", () => ({
  activateRecipe: vi.fn(),
  deactivateRecipe: vi.fn(),
  deleteRecipe: vi.fn(),
}));

import {
  activateRecipe,
  deactivateRecipe,
  deleteRecipe,
} from "../../../src/api/recipes";

const INACTIVE: Recipe = {
  id: "rec-2",
  name: "Tag billing questions",
  description: "",
  is_active: false,
  trigger_type: "keyword_detected",
  action_type: "auto_tag",
  channel_id: "",
  channel_type: "email",
  cooldown_minutes: 0,
};

const ACTIVE: Recipe = { ...INACTIVE, id: "rec-1", is_active: true };

function renderRow(recipe: Recipe, onChanged = vi.fn()) {
  render(
    <MemoryRouter>
      <RecipeRowActions recipe={recipe} onChanged={onChanged} />
    </MemoryRouter>,
  );
  return { onChanged };
}

describe("RecipeRowActions", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("toggles an inactive recipe on: calls activateRecipe and flips aria-checked optimistically", async () => {
    const user = userEvent.setup();
    let resolveActivate: (r: Recipe) => void = () => {};
    vi.mocked(activateRecipe).mockImplementation(
      () => new Promise<Recipe>((res) => { resolveActivate = res; }),
    );
    const { onChanged } = renderRow(INACTIVE);

    const sw = screen.getByRole("switch");
    expect(sw).toHaveAttribute("aria-checked", "false");

    await user.click(sw);

    // Optimistic: flips before the promise resolves.
    expect(sw).toHaveAttribute("aria-checked", "true");
    expect(activateRecipe).toHaveBeenCalledWith("rec-2");

    resolveActivate({ ...INACTIVE, is_active: true });
    await waitFor(() =>
      expect(onChanged).toHaveBeenCalledWith(
        expect.objectContaining({ id: "rec-2", is_active: true }),
      ),
    );
  });

  it("toggles an active recipe off: calls deactivateRecipe", async () => {
    const user = userEvent.setup();
    vi.mocked(deactivateRecipe).mockResolvedValue({ ...ACTIVE, is_active: false });
    renderRow(ACTIVE);

    const sw = screen.getByRole("switch");
    expect(sw).toHaveAttribute("aria-checked", "true");
    await user.click(sw);
    expect(deactivateRecipe).toHaveBeenCalledWith("rec-1");
  });

  it("rolls back to unchecked and shows an error when the toggle fails", async () => {
    const user = userEvent.setup();
    vi.mocked(activateRecipe).mockRejectedValue(new Error("boom"));
    renderRow(INACTIVE);

    const sw = screen.getByRole("switch");
    await user.click(sw);

    await waitFor(() =>
      expect(sw).toHaveAttribute("aria-checked", "false"),
    );
    expect(await screen.findByRole("alert")).toBeInTheDocument();
  });

  it("gives the activate/deactivate switch a 44px min tap target (WCAG 2.5.8), track visual unchanged", () => {
    renderRow(INACTIVE);
    const toggle = screen.getByRole("switch", { name: m.recipes_toggle_active_label() });
    expect(toggle.className).toMatch(/\bmin-h-tap\b/);
    expect(toggle.className).toMatch(/\bmin-w-tap\b/);
    // Visual track dimensions are preserved on the inner glyph, not blown
    // up to 44px, so the switch doesn't balloon into a fat pill. The track
    // is the button's first (aria-hidden) child element.
    const track = toggle.firstElementChild;
    expect(track).not.toBeNull();
    expect(track?.className).toMatch(/\bh-cog-4-5\b/);
    expect(track?.className).toMatch(/\bw-cog-6-5\b/);
  });

  it("inactive toggle carries a visible emphasized border (WCAG 1.4.11)", () => {
    renderRow(INACTIVE);
    const sw = screen.getByRole("switch");
    expect(sw).toHaveAttribute("aria-checked", "false");
    // The border lives on the inner aria-hidden track, not the button, so
    // the 44px tap target draws no box of its own.
    expect(sw.firstElementChild?.className).toMatch(
      /\bborder-cog-border-emphasized\b/,
    );
  });

  it("renders an Edit link to /dialogue/recipes/{id}/edit", () => {
    renderRow(INACTIVE);
    const link = screen.getByRole("link", { name: m.recipes_edit() });
    expect(link).toHaveAttribute("href", "/dialogue/recipes/rec-2/edit");
  });

  it("opens a confirm dialog, deletes on confirm, and calls onChanged(null)", async () => {
    const user = userEvent.setup();
    vi.mocked(deleteRecipe).mockResolvedValue();
    const { onChanged } = renderRow(INACTIVE);

    await user.click(screen.getByRole("button", { name: m.recipes_delete() }));

    const dialog = await screen.findByRole("alertdialog");
