  action("add_note", "Add a note", true, [
    { name: "template", type: "text", required: true, label: "Note template" },
  ]),
  action("assign_agent", "Assign agent", false),
  action("create_task", "Create task", false),
  action("notify_slack", "Notify Slack", false),
  action("webhook", "Call webhook", false),
  action("escalate", "Escalate", false),
  action("close_conversation", "Close conversation", false),
  action("snooze", "Snooze", false),
];

