// Tests for SchemaFields — the schema-driven config-field renderer.
//
// Verifies, per field type:
//   - string_list → keyword chip input.
//   - enum:any|all → a radio group (Any/All); selecting All fires
//     onChange("match","all").
//   - uuid (group_id) → a select populated from groups; selecting fires
//     onChange("group_id", id).
//   - int → a number input.
//
// Queries by role/label — never getByTestId.

import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, it, expect, vi } from "vitest";
import { SchemaFields } from "../../../src/components/recipes/SchemaFields";
import type { ConfigField } from "../../../src/recipes/schema";

const keywordFields: ConfigField[] = [
  { name: "keywords", type: "string_list", required: true, label: "Keywords" },
  { name: "match", type: "enum:any|all", required: false, label: "Match" },
];

describe("SchemaFields", () => {
  it("renders a chip input and a radio group for keyword_detected fields", () => {
    render(
      <SchemaFields
        fields={keywordFields}
        value={{ keywords: [], match: "any" }}
        onChange={vi.fn()}
      />,
    );
    // chip input
    expect(screen.getByLabelText("Keywords")).toBeInTheDocument();
    // radio group with two options
    const radios = screen.getAllByRole("radio");
    expect(radios).toHaveLength(2);
  });

  it("fires onChange(match, all) when the All radio is selected", async () => {
    const user = userEvent.setup();
    const onChange = vi.fn();
    render(
      <SchemaFields
        fields={keywordFields}
        value={{ keywords: [], match: "any" }}
        onChange={onChange}
      />,
    );
    const radios = screen.getAllByRole("radio");
    // second radio = "all" (any first, all second)
    await user.click(radios[1]);
    expect(onChange).toHaveBeenCalledWith("match", "all");
  });

  it("renders a populated select for a uuid group_id field and fires onChange on selection", async () => {
    const user = userEvent.setup();
    const onChange = vi.fn();
    const fields: ConfigField[] = [
      { name: "group_id", type: "uuid", required: true, label: "Contact group" },
    ];
    render(
      <SchemaFields
        fields={fields}
        value={{ group_id: "" }}
        onChange={onChange}
        groups={[{ id: "g1", name: "VIP" }]}
      />,
    );
    const select = screen.getByLabelText(/Contact group/);
    expect(screen.getByRole("option", { name: "VIP" })).toBeInTheDocument();
    await user.selectOptions(select, "g1");
    expect(onChange).toHaveBeenCalledWith("group_id", "g1");
  });

  it("renders a number input for an int field", () => {
    const fields: ConfigField[] = [
      { name: "priority", type: "int", required: false, label: "Priority" },
    ];
    render(
      <SchemaFields fields={fields} value={{ priority: 0 }} onChange={vi.fn()} />,
    );
    const input = screen.getByLabelText(/Priority/);
    expect(input).toHaveAttribute("type", "number");
  });

  it("renders a checked checkbox for a bool field defaulting true", () => {
    const fields: ConfigField[] = [
      { name: "require_approval", type: "bool", required: false, label: "Require approval" },
    ];
    render(
      <SchemaFields fields={fields} value={{ require_approval: true }} onChange={vi.fn()} />,
    );
    const checkbox = screen.getByLabelText(/Require approval/);
    expect(checkbox).toHaveAttribute("type", "checkbox");
